//! Lifecycle tests against a recording fake wrangler.
//!
//! `tests/fixtures/fake-wrangler.sh` keeps a small Cloudflare account in
//! files and answers with wrangler 4.129.0's output shapes (JSON on stdout,
//! ND-JSON records in `WRANGLER_OUTPUT_FILE_PATH`, `[code: N]` errors and
//! non-zero exits). The artifact under test is generated by the real
//! Cloudflare build adapter, so a drift between what the adapter writes and
//! what the driver rewrites fails here.

use std::collections::BTreeMap;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};

use deis_provider_driver::{
    DeploymentState, DriverErrorCategory, DriverNextAction, DriverOperation, DriverReceipt,
    DriverReconcileContext, DriverRequest, DriverRollbackTarget, ProviderNeutralPlan,
    ProviderTargetRef, SideEffect,
};
use deis_provider_driver_cloudflare::commands::{OperationContext, Timeouts, execute_operation};
use deis_provider_driver_cloudflare::credentials::CloudflareCredential;
use deis_provider_driver_cloudflare::environment::SecretValues;
use deis_provider_driver_cloudflare::journal::JournalStore;
use deis_provider_driver_cloudflare::naming::DeploymentScope;
use deis_provider_driver_cloudflare::wrangler::Wrangler;
use deis_wire::CanonicalId;

const TOKEN: &str = "test-api-token-4f1d";
const ACCOUNT: &str = "0123456789abcdef0123456789abcdef";
const DIGEST_A: &str = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
const DIGEST_B: &str = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";

/// The project the artifact is built from: every resource kind, a consumed
/// queue, a cron, one config value and one secret.
fn project() -> deis_build_core::ProjectConfig {
    serde_json::from_value(serde_json::json!({
        "version": "1.0",
        "name": "shop",
        "runtime": "standard-v1",
        "language": "typescript",
        "compatibilityDate": "2026-09-01",
        "bindings": {
            "HOT": {"kind": "kv"},
            "DB": {"kind": "database"},
            "FILES": {"kind": "blob"},
            "ORDERS": {"kind": "queue"}
        },
        "queues": [{"name": "ORDERS"}, {"name": "JOBS"}],
        "cron": ["*/5 * * * *"],
        "environment": {
            "variables": {"GREETING": "unused-at-build"},
            "secrets": ["API_KEY"]
        }
    }))
    .expect("project config parses")
}

struct Harness {
    root: tempfile::TempDir,
    app: CanonicalId,
    env: CanonicalId,
    wrangler: Wrangler,
    credential: CloudflareCredential,
    config: BTreeMap<String, String>,
    secrets: SecretValues,
    purge: Option<String>,
}

impl Harness {
    fn new() -> Self {
        let root = tempfile::tempdir().unwrap();
        let state = root.path().join("account");
        fs::create_dir_all(state.join("fail")).unwrap();
        let script =
            include_str!("fixtures/fake-wrangler.sh").replace("__STATE__", state.to_str().unwrap());
        let program = root.path().join("fake-wrangler");
        fs::write(&program, script).unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();

        let artifacts = deis_build_adapter_cloudflare::generate(
            &[("/".to_owned(), "./handlers/index.ts".to_owned())],
            &project(),
            &[],
        )
        .expect("adapter generates the artifact");
        let artifact = root.path().join("artifact");
        fs::create_dir_all(&artifact).unwrap();
        for (name, contents) in &artifacts.config_files {
            fs::write(artifact.join(name), contents).unwrap();
        }
        fs::write(artifact.join("index.js"), artifacts.router_code).unwrap();

        let credential = CloudflareCredential::from_env_value(&format!(
            r#"{{"api_token":"{TOKEN}","account_id":"{ACCOUNT}"}}"#
        ))
        .unwrap();
        Self {
            wrangler: Wrangler::from_program(program, root.path().join("driver/home")),
            root,
            app: "01890a5d-ac96-774b-bcce-b302099a8057".parse().unwrap(),
            env: "01890a5d-ac96-774b-bcce-b302099a8059".parse().unwrap(),
            credential,
            config: BTreeMap::from([("GREETING".to_owned(), "hello".to_owned())]),
            secrets: SecretValues::default(),
            purge: None,
        }
    }

    fn state(&self) -> PathBuf {
        self.root.path().join("account")
    }

    fn artifact(&self) -> PathBuf {
        self.root.path().join("artifact")
    }

    fn scope(&self) -> DeploymentScope {
        DeploymentScope::new(&self.app, &self.env)
    }

    fn request(&self, operation: DriverOperation, digest: &str) -> DriverRequest {
        DriverRequest {
            schema_version: 1,
            operation_id: CanonicalId::new_v7(),
            operation,
            desired_state_digest: digest.parse().unwrap(),
            application_id: self.app,
            environment_id: self.env,
            target: ProviderTargetRef {
                provider_target_id: CanonicalId::new_v7(),
                provider_installation_id: CanonicalId::new_v7(),
                backend_id: "cloudflare-workers-pages".to_owned(),
                target_config_digest: DIGEST_B.parse().unwrap(),
            },
            artifact: None,
            plan: ProviderNeutralPlan::default(),
            rollback_target: None,
            reconciles: None,
        }
    }

    async fn execute(
        &self,
        request: &DriverRequest,
    ) -> Result<DriverReceipt, deis_provider_driver::DriverError> {
        let journals = JournalStore::new(&self.root.path().join("driver/state"));
        let scratch = self.root.path().join("driver/work");
        let artifact = self.artifact();
        let context = OperationContext {
            wrangler: &self.wrangler,
            credential: &self.credential,
            artifact_dir: &artifact,
            journals: &journals,
            scratch_root: &scratch,
            config: &self.config,
            secrets: &self.secrets,
            purge_environment_id: self.purge.as_deref(),
            timeouts: Timeouts::default(),
        };
        execute_operation(&context, request).await
    }

    async fn run(&self, operation: DriverOperation) -> DriverReceipt {
        self.run_for(operation, DIGEST_A).await
    }

    async fn run_for(&self, operation: DriverOperation, digest: &str) -> DriverReceipt {
        let request = self.request(operation, digest);
        match self.execute(&request).await {
            Ok(receipt) => receipt,
            Err(error) => panic!("{operation:?} failed: {error:?}"),
        }
    }

    async fn fail_with(&self, operation: DriverOperation) -> deis_provider_driver::DriverError {
        let request = self.request(operation, DIGEST_A);
        self.execute(&request)
            .await
            .expect_err("operation must fail")
    }

    fn inject_failure(&self, key: &str, exit: i32, code: u64, message: &str) {
        fs::write(
            self.state().join("fail").join(key),
            format!("{exit}|{code}|{message}\n"),
        )
        .unwrap();
    }

    fn clear_failure(&self, key: &str) {
        fs::remove_file(self.state().join("fail").join(key)).unwrap();
    }

    fn argv(&self) -> Vec<String> {
        fs::read_to_string(self.state().join("argv.log"))
            .unwrap_or_default()
            .lines()
            .map(str::to_owned)
            .collect()
    }

    fn calls_starting(&self, prefix: &str) -> Vec<String> {
        self.argv()
            .into_iter()
            .filter(|line| line.starts_with(prefix))
            .collect()
    }

    fn call_index(&self, prefix: &str) -> usize {
        self.argv()
            .iter()
            .position(|line| line.starts_with(prefix))
            .unwrap_or_else(|| panic!("no call starting with {prefix:?}"))
            + 1
    }

    fn names_in(&self, kind_dir: &str) -> Vec<String> {
        let mut names = fs::read_dir(self.state().join(kind_dir))
            .map(|entries| {
                entries
                    .flatten()
                    .map(|entry| entry.file_name().to_string_lossy().into_owned())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        names.sort();
        names
    }
}

fn list_dir(path: &Path) -> Vec<String> {
    let mut names = fs::read_dir(path)
        .map(|entries| {
            entries
                .flatten()
                .map(|entry| entry.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_else(|_| Vec::new());
    names.sort();
    names
}

// ── exit codes ──────────────────────────────────────────────────────────────

#[tokio::test]
async fn preflight_runs_whoami_and_propagates_a_non_zero_exit() {
    let harness = Harness::new();
    harness.run(DriverOperation::Preflight).await;
    assert_eq!(harness.argv(), vec!["whoami --json"]);

    harness.inject_failure("whoami", 1, 10000, "Authentication error");
    let error = harness.fail_with(DriverOperation::Preflight).await;
    assert_eq!(error.category, DriverErrorCategory::Authentication);
    assert_eq!(error.code, "WRANGLER_AUTHENTICATION");
    assert!(error.message.contains("10000"), "{}", error.message);
}

#[tokio::test]
async fn a_failed_upload_is_an_error_with_a_possible_side_effect() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    harness.inject_failure("versions-upload", 1, 10021, "Uploaded script has errors");
    let error = harness.fail_with(DriverOperation::Upload).await;
    assert_eq!(error.code, "WRANGLER_COMMAND_FAILED");
    assert_eq!(error.category, DriverErrorCategory::Upload);
    assert_eq!(error.side_effect, SideEffect::Possible);
    assert_eq!(error.next_action, DriverNextAction::Reconcile);
    assert!(
        error.message.contains("Uploaded script has errors"),
        "{}",
        error.message
    );

    // And the failure left no uploaded version for activate to deploy.
    let error = harness.fail_with(DriverOperation::Activate).await;
    assert_eq!(error.code, "UPLOAD_MISSING");
    assert!(harness.calls_starting("versions deploy").is_empty());
}

#[tokio::test]
async fn a_failed_activate_is_an_error() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    harness.run(DriverOperation::Upload).await;
    harness.inject_failure("versions-deploy", 1, 10214, "deployment failed");
    let error = harness.fail_with(DriverOperation::Activate).await;
    assert_eq!(error.category, DriverErrorCategory::Activation);
    assert_eq!(error.side_effect, SideEffect::Possible);
}

// ── placeholder resolution and namespacing ─────────────────────────────────

#[tokio::test]
async fn prepare_creates_scoped_resources_then_reuses_them() {
    let harness = Harness::new();
    let scope = harness.scope();
    let first = harness.run(DriverOperation::Prepare).await;

    let prefix = scope.resource_prefix();
    assert_eq!(harness.names_in("kv"), vec![format!("{prefix}kv-hot")]);
    assert_eq!(harness.names_in("d1"), vec![format!("{prefix}d1-db")]);
    assert_eq!(harness.names_in("r2"), vec![format!("{prefix}r2-files")]);
    assert_eq!(
        harness.names_in("queues"),
        vec![format!("{prefix}q-jobs"), format!("{prefix}q-orders")],
        "the producer queue and the consume-only queue are both provisioned"
    );
    assert_eq!(harness.calls_starting("kv namespace create").len(), 1);
    assert_eq!(harness.calls_starting("d1 create").len(), 1);
    assert_eq!(harness.calls_starting("r2 bucket create").len(), 1);
    assert_eq!(harness.calls_starting("queues create").len(), 2);
    assert_eq!(first.side_effect, SideEffect::Confirmed);
    assert_eq!(first.provider_resource_ids["worker"], scope.worker_name());
    assert!(first.provider_resource_ids["kv:HOT"].starts_with("kvid"));

    let creates_before = harness
        .argv()
        .iter()
        .filter(|line| line.contains(" create "))
        .count();
    let second = harness.run(DriverOperation::Prepare).await;
    let creates_after = harness
        .argv()
        .iter()
        .filter(|line| line.contains(" create "))
        .count();
    assert_eq!(
        creates_before, creates_after,
        "a re-prepare creates nothing"
    );
    assert_eq!(first.provider_resource_ids, second.provider_resource_ids);
}

#[tokio::test]
async fn prepare_adopts_resources_that_exist_without_a_journal() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    let ids = harness
        .run(DriverOperation::Prepare)
        .await
        .provider_resource_ids;
    // A fresh driver state directory (journal lost) finds the same resources.
    fs::remove_dir_all(harness.root.path().join("driver/state")).unwrap();
    let adopted = harness
        .run(DriverOperation::Prepare)
        .await
        .provider_resource_ids;
    assert_eq!(ids, adopted);
    assert_eq!(harness.calls_starting("kv namespace create").len(), 1);
}

#[tokio::test]
async fn two_applications_in_one_account_never_share_a_resource() {
    let first = Harness::new();
    let mut second = Harness::new();
    // Same fake account, different application.
    second.wrangler = first.wrangler.clone();
    second.app = "01890a5d-ac96-774b-bcce-b302099a8058".parse().unwrap();

    let a = first
        .run(DriverOperation::Prepare)
        .await
        .provider_resource_ids;
    let b = second
        .run(DriverOperation::Prepare)
        .await
        .provider_resource_ids;
    assert_ne!(a["kv:HOT"], b["kv:HOT"]);
    assert_ne!(a["d1:DB"], b["d1:DB"]);
    assert_ne!(a["r2:FILES"], b["r2:FILES"]);
    assert_ne!(a["worker"], b["worker"]);
    assert_eq!(first.names_in("kv").len(), 2);
}

#[tokio::test]
async fn upload_deploys_a_fully_resolved_wrangler_toml() {
    let harness = Harness::new();
    let prepared = harness.run(DriverOperation::Prepare).await;
    let uploaded = harness.run(DriverOperation::Upload).await;
    assert_eq!(uploaded.deployment_state, Some(DeploymentState::Uploaded));
    let version = uploaded.provider_version_id.clone().expect("version id");

    let index = harness.call_index("versions upload");
    let toml = fs::read_to_string(harness.state().join(format!("cwd.{index}"))).unwrap();
    assert!(!toml.contains("deis:unresolved"), "{toml}");
    let scope = harness.scope();
    let ids = &prepared.provider_resource_ids;
    assert!(
        toml.contains(&format!("name = \"{}\"", scope.worker_name())),
        "{toml}"
    );
    assert!(
        toml.contains(&format!("id = \"{}\"", ids["kv:HOT"])),
        "{toml}"
    );
    assert!(
        toml.contains(&format!("database_id = \"{}\"", ids["d1:DB"])),
        "{toml}"
    );
    assert!(
        toml.contains(&format!(
            "database_name = \"{}\"",
            scope.resource_name(deis_build_core::BindingKind::Database, "DB")
        )),
        "{toml}"
    );
    assert!(
        toml.contains(&format!("bucket_name = \"{}\"", ids["r2:FILES"])),
        "{toml}"
    );
    assert!(
        toml.contains(&format!(
            "queue = \"{}\"",
            scope.resource_name(deis_build_core::BindingKind::Queue, "JOBS")
        )),
        "consumers point at the scoped queue: {toml}"
    );
    assert!(toml.contains("GREETING = \"hello\""), "{toml}");
    assert!(toml.contains("crons = [\"*/5 * * * *\"]"), "{toml}");
    // The source artifact is untouched.
    let source = fs::read_to_string(harness.artifact().join("wrangler.toml")).unwrap();
    assert!(source.contains("deis:unresolved/kv/HOT"));

    let activated = harness.run(DriverOperation::Activate).await;
    assert_eq!(
        activated.provider_version_id.as_deref(),
        Some(version.as_str())
    );
    assert!(activated.provider_deployment_id.is_some());
    let deploy = harness.calls_starting("versions deploy");
    assert_eq!(deploy.len(), 1);
    assert!(deploy[0].starts_with(&format!(
        "versions deploy {version}@100% --name {}",
        scope.worker_name()
    )));

    let observed = harness.run(DriverOperation::Observe).await;
    assert_eq!(observed.deployment_state, Some(DeploymentState::Active));
    let verified = harness.run(DriverOperation::Verify).await;
    assert_eq!(verified.deployment_state, Some(DeploymentState::Ready));
}

#[tokio::test]
async fn upload_refuses_a_placeholder_it_cannot_resolve() {
    let mut harness = Harness::new();
    harness.config.clear();
    let error = harness.fail_with(DriverOperation::Plan).await;
    assert_eq!(error.code, "PLACEHOLDER_UNRESOLVED");
    assert!(
        error.message.contains("deis:unresolved/config/GREETING"),
        "{}",
        error.message
    );

    harness
        .config
        .insert("GREETING".to_owned(), "hi".to_owned());
    // Without prepare, the resource placeholders have no identifiers.
    let error = harness.fail_with(DriverOperation::Upload).await;
    assert_eq!(error.code, "PLACEHOLDER_UNRESOLVED");
    assert!(
        harness.calls_starting("versions upload").is_empty(),
        "nothing was uploaded"
    );
}

#[tokio::test]
async fn plan_refuses_an_artifact_that_disagrees_with_its_binding_plan() {
    let harness = Harness::new();
    let path = harness.artifact().join("wrangler.toml");
    let toml = fs::read_to_string(&path).unwrap();
    fs::write(
        &path,
        toml.replace("binding = \"HOT\"", "binding = \"COLD\""),
    )
    .unwrap();
    let error = harness.fail_with(DriverOperation::Plan).await;
    assert_eq!(error.code, "ARTIFACT_INVALID");
    assert!(harness.argv().is_empty(), "plan never reaches wrangler");
}

// ── secrets and credentials ────────────────────────────────────────────────

#[tokio::test]
async fn secrets_reach_wrangler_on_stdin_only() {
    let mut harness = Harness::new();
    harness.secrets = SecretValues::new(BTreeMap::from([(
        "API_KEY".to_owned(),
        "sk-live-very-secret".to_owned(),
    )]))
    .unwrap();
    harness.run(DriverOperation::Prepare).await;
    harness.run(DriverOperation::Upload).await;

    let index = harness.call_index("versions upload");
    let upload = &harness.argv()[index - 1];
    assert!(upload.contains("--secrets-file /dev/stdin"), "{upload}");
    let stdin: serde_json::Value =
        serde_json::from_slice(&fs::read(harness.state().join(format!("stdin.{index}"))).unwrap())
            .unwrap();
    assert_eq!(stdin, serde_json::json!({"API_KEY": "sk-live-very-secret"}));

    for line in harness.argv() {
        assert!(
            !line.contains("sk-live-very-secret"),
            "secret in argv: {line}"
        );
        assert!(!line.contains(TOKEN), "token in argv: {line}");
    }
    let staged = list_dir(&harness.root.path().join("driver/work"));
    assert!(staged.is_empty(), "staging is removed: {staged:?}");
}

#[tokio::test]
async fn the_credential_goes_to_the_environment_and_never_into_errors() {
    let harness = Harness::new();
    harness.inject_failure("whoami", 1, 9109, &format!("Invalid access token {TOKEN}"));
    let error = harness.fail_with(DriverOperation::Preflight).await;
    assert!(!error.message.contains(TOKEN), "{}", error.message);
    assert!(error.message.contains("[redacted]"), "{}", error.message);

    let env = fs::read_to_string(harness.state().join("env.log")).unwrap();
    assert_eq!(
        env.lines().next(),
        Some(format!("{TOKEN}|{ACCOUNT}|home").as_str())
    );
}

// ── delete and cleanup ─────────────────────────────────────────────────────

#[tokio::test]
async fn delete_removes_the_worker_and_keeps_data_without_consent() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    harness.run(DriverOperation::Upload).await;
    harness.run(DriverOperation::Activate).await;
    let worker = harness.scope().worker_name();

    let deleted = harness.run(DriverOperation::Delete).await;
    assert_eq!(
        harness.calls_starting("delete"),
        vec![format!("delete {worker} --force")]
    );
    assert!(harness.names_in("workers").is_empty());
    assert_eq!(
        harness.names_in("kv").len(),
        1,
        "data retained without consent"
    );
    assert!(
        deleted
            .diagnostic
            .unwrap()
            .contains("DEIS_CLOUDFLARE_PURGE_DATA")
    );

    // Deleting again is idempotent: Cloudflare's not-found is success.
    harness.run(DriverOperation::Delete).await;

    // Any other failure is an error.
    harness.inject_failure("delete", 1, 10000, "Authentication error");
    let error = harness.fail_with(DriverOperation::Delete).await;
    assert_eq!(error.category, DriverErrorCategory::Authentication);
}

#[tokio::test]
async fn consented_purge_destroys_only_this_environments_resources() {
    let mut harness = Harness::new();
    let mut neighbour = Harness::new();
    neighbour.wrangler = harness.wrangler.clone();
    neighbour.env = "01890a5d-ac96-774b-bcce-b302099a805a".parse().unwrap();
    neighbour.run(DriverOperation::Prepare).await;

    harness.run(DriverOperation::Prepare).await;
    harness.run(DriverOperation::Upload).await;
    harness.run(DriverOperation::Activate).await;

    // Consent for another environment is no consent.
    harness.purge = Some(neighbour.env.to_string());
    harness.run(DriverOperation::Delete).await;
    assert_eq!(harness.names_in("kv").len(), 2);

    harness.purge = Some(harness.env.to_string());
    let receipt = harness.run(DriverOperation::Cleanup).await;
    assert_eq!(receipt.side_effect, SideEffect::Confirmed);
    let neighbour_prefix = neighbour.scope().resource_prefix();
    for kind in ["kv", "d1", "r2", "queues"] {
        let left = harness.names_in(kind);
        assert!(
            left.iter().all(|name| name.starts_with(&neighbour_prefix)),
            "{kind}: {left:?}"
        );
        assert!(
            !left.is_empty(),
            "{kind}: the neighbour's resources survive"
        );
    }
    assert!(harness.calls_starting("kv namespace delete").len() == 1);
    assert!(harness.calls_starting("d1 delete").len() == 1);
    assert!(harness.calls_starting("r2 bucket delete").len() == 1);
    assert!(harness.calls_starting("queues delete").len() == 2);
}

#[tokio::test]
async fn purge_refuses_while_the_worker_still_serves() {
    let mut harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    harness.run(DriverOperation::Upload).await;
    harness.run(DriverOperation::Activate).await;
    harness.purge = Some(harness.env.to_string());
    let error = harness.fail_with(DriverOperation::Cleanup).await;
    assert_eq!(error.code, "PURGE_WHILE_WORKER_EXISTS");
    assert_eq!(harness.names_in("kv").len(), 1);
}

// ── rollback and reconcile ─────────────────────────────────────────────────

#[tokio::test]
async fn rollback_redeploys_the_target_version() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    let first = harness
        .run(DriverOperation::Upload)
        .await
        .provider_version_id
        .unwrap();
    harness.run(DriverOperation::Activate).await;
    harness.run_for(DriverOperation::Upload, DIGEST_B).await;
    harness.run_for(DriverOperation::Activate, DIGEST_B).await;

    let mut request = harness.request(DriverOperation::Rollback, DIGEST_A);
    request.rollback_target = Some(DriverRollbackTarget {
        source_operation_id: CanonicalId::new_v7(),
        activation_operation_id: CanonicalId::new_v7(),
        activation_receipt_sha256: DIGEST_B.parse().unwrap(),
        provider_deployment_id: None,
        provider_version_id: Some(first.clone()),
        provider_resource_ids: BTreeMap::new(),
    });
    let receipt = harness.execute(&request).await.unwrap();
    assert_eq!(receipt.deployment_state, Some(DeploymentState::RolledBack));
    let observed = harness.run(DriverOperation::Observe).await;
    assert_eq!(
        observed.provider_version_id.as_deref(),
        Some(first.as_str())
    );
}

#[tokio::test]
async fn reconcile_of_an_upload_finds_the_version_by_its_desired_state() {
    let harness = Harness::new();
    harness.run(DriverOperation::Prepare).await;
    let uploaded = harness
        .run(DriverOperation::Upload)
        .await
        .provider_version_id;
    // The outcome was lost: a fresh journal must still find the version.
    fs::remove_dir_all(harness.root.path().join("driver/state")).unwrap();

    let mut request = harness.request(DriverOperation::Reconcile, DIGEST_A);
    request.reconciles = Some(DriverReconcileContext {
        operation: DriverOperation::Upload,
    });
    let receipt = harness.execute(&request).await.unwrap();
    assert_eq!(receipt.provider_version_id, uploaded);

    let mut request = harness.request(DriverOperation::Reconcile, DIGEST_B);
    request.reconciles = Some(DriverReconcileContext {
        operation: DriverOperation::Upload,
    });
    let error = harness.execute(&request).await.unwrap_err();
    assert_eq!(error.code, "NOT_APPLIED");
    assert_eq!(error.side_effect, SideEffect::None);
}

#[tokio::test]
async fn an_authentication_failure_while_probing_a_bucket_is_not_absence() {
    let harness = Harness::new();
    harness.inject_failure("r2-bucket", 1, 10000, "Authentication error");
    let error = harness.fail_with(DriverOperation::Prepare).await;
    assert_eq!(error.category, DriverErrorCategory::Authentication);
    assert!(harness.calls_starting("r2 bucket create").is_empty());
}

#[tokio::test]
async fn failures_clear_once_the_provider_recovers() {
    let harness = Harness::new();
    harness.inject_failure("whoami", 1, 10013, "temporary");
    harness.fail_with(DriverOperation::Preflight).await;
    harness.clear_failure("whoami");
    harness.run(DriverOperation::Preflight).await;
}
